"""This file contains the Volume View Reference Page Object class for the VolumeView Reference window in XVI.
This window is normally displayed after the a 3D Dicom data import has been done."""

import logging
from .. interactions import VolumeViewRefFuncs
from interops.libraries.desktop import AutManager
from interops.libraries.xvi import XviAutController
from interops.libraries.squish_actions.constants import XVI_REGISTRATION_APP_NAME
from typing import Dict

logger = logging.getLogger(__name__)

class VolumeViewReference():

    def __init__(self, host_address="192.168.30.4", aut_attach_retries: int = 3) -> None:
        # Check if squish has already attached to XVI3 AUT, if not attach to it
        # Note: The XVI VolumeView Reference AUT name (xvi3) is the same as the VolumeView Registration AUT
        if not AutManager.is_aut_running(XVI_REGISTRATION_APP_NAME):
            xvi_vol_view_ref_driver = XviAutController.xvi_registration_aut(serverAddress=host_address, serverPort=4322)
            for i in range(aut_attach_retries):
                try:
                    print(f"xvi3 attach attempt no. {i+1}")
                    self.xvi3_volume_view_driver = xvi_vol_view_ref_driver.attach_to_aut(kill_existing_process=True, get_running_aut_pid_retries=200)
                except Exception as e:
                    logger.info(f"Failed to attach to VolumeView Reference window on attempt no: {i+1}. Error: {e}.")
        self.xvi_host_address = host_address

    def ready(self, wait_timeout=3000, retries: int=2) -> bool:
        '''
        Waits for the VolumeView Reference window to be ready.

        Returns:
            bool - True if VolumeView Reference window is ready, False otherwise
        '''
        for i in range(retries):
            try:
                return VolumeViewRefFuncs.wait_for_volume_view_reconstruction_pane(wait_timeout)
            except Exception as e:
                logger.info(f"VolumeView Reference window failed to open or was not recognised on attempt no: {i+1}. Error: {e}.")
        return False

    def toggle_reference_clipbox_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Clipbox checkbox in the Reference Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            VolumeViewRefFuncs.check_volume_view_reference_clipbox_checkbox()
        else:
            VolumeViewRefFuncs.uncheck_volume_view_reference_clipbox_checkbox()

    def toggle_reference_cor_ref_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Cor Ref checkbox in the Reference Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            VolumeViewRefFuncs.check_volume_view_registration_reference_cor_ref_checkbox()
        else:
            VolumeViewRefFuncs.uncheck_volume_view_registration_reference_cor_ref_checkbox()

    def toggle_reference_clipbox_locked_context_menu_item(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Clipbox Locked context menu item in the Reference Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            VolumeViewRefFuncs.check_volume_view_reference_clipbox_locked_context_menu_item()
        else:
            VolumeViewRefFuncs.uncheck_volume_view_reference_clipbox_locked_context_menu_item()

    def select_cor_ref_isocenter_context_menu_item(self) -> None:
        '''
        Selects the Cor Ref Isocenter context menu item in the Reference Pane
        '''
        VolumeViewRefFuncs.click_volume_view_reference_cor_ref_isocenter_context_menu_item()

    def select_cor_ref_center_of_reg_clipbox_context_menu_item(self) -> None:
        '''
        Selects the Cor Ref Center of registration clipbox context menu item in the Reference Pane
        '''
        VolumeViewRefFuncs.click_volume_view_reference_cor_ref_center_of_reg_clipbox_context_menu_item()

    def select_cor_ref_center_of_structure_ptv45_context_menu_item(self) -> None:
        '''
        Selects the Cor Ref Center of structure PTV_45 context menu item in the Reference Pane
        '''
        VolumeViewRefFuncs.click_volume_view_reference_cor_ref_center_of_reg_clipbox_context_menu_item()

    def select_mask_create_from_ptv_context_menu_item(self) -> None:
        '''
        Selects the Mask button followed by the "Create from" > "PTV" context menu items in the Reference Pane
        '''
        VolumeViewRefFuncs.click_volume_view_reference_mask_create_from_ptv_context_menu_item()

    def edit_margin_for_mask_dialog_value_field(self, mask_margin_value: float) -> None:
        '''
        Checks and waits for the Margin for Mask (0-2 cm) dialog to appear, enters the
        specified value and clicks the OK button.

        Args:
            mask_margin_value (float): Mask Margin value (in cm) to enter in the Value field, should be between 0 and 2 cm
        '''
        VolumeViewRefFuncs.edit_margin_for_mask_field(mask_margin_value)
        VolumeViewRefFuncs.click_volume_view_reference_margin_for_mask_ok_button()

    def select_protocol_registration_combobox_option(self, protocol_reg: str) -> None:
        '''
        Select one of the protocol registration options from the combobox
        for the given method string

        Args:
            reg_method (str): Name of the protocol registration to select from the combobox

            reg_method can be one of the following strings:
            "Clipbox", "Mask" or "Dual Registration"
        '''
        if protocol_reg.casefold() == "Clipbox".casefold():
            VolumeViewRefFuncs.select_volume_view_protocol_registration_clipbox_option()
        elif protocol_reg.casefold() == "Mask".casefold():
            VolumeViewRefFuncs.select_volume_view_protocol_registration_mask_option()
        elif protocol_reg.casefold() == "Dual Registration".casefold():
            VolumeViewRefFuncs.select_volume_view_protocol_registration_dual_registration_option()
        else:
            logger.info(f"Invalid Protocol Registration: {protocol_reg}, unable to set")

    def get_current_registration_method(self) -> str:
        '''
        Gets the current registration method text from the VolumeView Registration Method ComboBox

        Returns:
            str - Registration method text
        '''
        return VolumeViewRefFuncs.get_current_volume_view_registration_method_from_combobox()

    def select_registration_method_combobox_option(self, reg_method: str) -> None:
        '''
        Select one of the methods from the registration (clipbox) method combobox
        for the given method string

        Args:
            reg_method (str): Name of the registration method to select from the combobox

            reg_method can be one of the following strings:
            "Manual", "Bone (T+R)", "Seed (T+R)", "Seed (T)", "Grey Value (T+R)" or
            "Grey Value (T)"
        '''
        if reg_method.casefold() == "Manual".casefold():
            VolumeViewRefFuncs.select_volume_view_registration_method_manual()
        elif reg_method.casefold() == "Bone (T+R)".casefold():
            VolumeViewRefFuncs.select_volume_view_registration_method_bone_t_and_r()
        elif reg_method.casefold() == "Seed (T+R)".casefold():
            VolumeViewRefFuncs.select_volume_view_registration_method_seed_t_and_r()
        elif reg_method.casefold() == "Seed (T)".casefold():
            VolumeViewRefFuncs.select_volume_view_registration_method_seed_t()
        elif reg_method.casefold() == "Grey Value (T+R)".casefold():
            VolumeViewRefFuncs.select_volume_view_registration_method_grey_t_and_r()
        elif reg_method.casefold() == "Grey Value (T)".casefold():
            VolumeViewRefFuncs.select_volume_view_registration_method_grey_t()
        else:
            logger.info(f"Invalid Registration method: {reg_method}, unable to set")

    def select_volume_view_reference_dismiss_button(self) -> None:
        '''
        Clicks the Dismiss button on the VolumeView Reference window
        '''
        VolumeViewRefFuncs.click_volume_view_reference_dismiss_button()

    def select_volume_view_reference_accept_button(self) -> None:
        '''
        Clicks the Accept button on the VolumeView Reference window
        '''
        VolumeViewRefFuncs.click_volume_view_reference_accept_button()

    def edit_comment_and_approve_reference_dialog(self, approval_comment: str) -> None:
        '''
        Checks and waits for the reference approval dialog to appear, enters the
        specified approval comment or initials and clicks the OK button.
        '''
        VolumeViewRefFuncs.edit_volume_view_reference_approval_comment_field(approval_comment)
        VolumeViewRefFuncs.click_volume_view_reference_approval_ok_button()